def code(html):
    for zh, en in sorted(CODE, key=lambda p: -len(p[0])):
        html = html.replace(zh, en)
    return html

def data(d):   # 通用版：数据里的字自己带英文（xxx_en），网页自己挑，这里不用换
    return d
